import { memo, useMemo, useState, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { useUserTokens } from 'uniswap/src/contexts/UserTokensContext'
import { TokenSelectorList } from 'uniswap/src/components/TokenSelector/TokenSelectorList'
import { useAddToSearchHistory } from 'uniswap/src/components/TokenSelector/hooks/useAddToSearchHistory'
import { useTokenSectionsForSearchResults } from 'uniswap/src/components/TokenSelector/hooks/useTokenSectionsForSearchResults'
import { OnSelectCurrency } from 'uniswap/src/components/TokenSelector/types'
import { NoResultsFound } from 'uniswap/src/components/lists/NoResultsFound'
import { TradeableAsset } from 'uniswap/src/entities/assets'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ImportTokenWarning } from 'uniswap/src/components/TokenSelector/ImportTokenWarning'
import { SafetyLevel } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { OnchainItemSection } from 'uniswap/src/components/lists/OnchainItemList/types'
import { TokenOption } from 'uniswap/src/components/lists/items/types'
import { isAddress } from 'utilities/src/addresses'

function _TokenSelectorSearchResultsList({
  onSelectCurrency: parentOnSelectCurrency,
  activeAccountAddress,
  chainFilter,
  parsedChainFilter,
  searchFilter,
  debouncedSearchFilter,
  debouncedParsedSearchFilter,
  isBalancesOnlySearch,
  isKeyboardOpen,
  input,
}: {
  onSelectCurrency: OnSelectCurrency
  activeAccountAddress?: string
  chainFilter: UniverseChainId | null
  parsedChainFilter: UniverseChainId | null
  searchFilter: string
  debouncedSearchFilter: string | null
  debouncedParsedSearchFilter: string | null
  isBalancesOnlySearch: boolean
  isKeyboardOpen?: boolean
  input: TradeableAsset | undefined
}): JSX.Element {
  const { t } = useTranslation()
  const { registerSearchTokenCurrencyInfo } = useAddToSearchHistory()
  const { addUserToken } = useUserTokens()
  const [pendingImportToken, setPendingImportToken] = useState<{
    currencyInfo: CurrencyInfo
    section: OnchainItemSection<TokenOption>
    index: number
  } | null>(null)

  const {
    data: sections,
    loading,
    error,
    refetch,
  } = useTokenSectionsForSearchResults(
    activeAccountAddress,
    chainFilter ?? parsedChainFilter,
    debouncedParsedSearchFilter ?? debouncedSearchFilter,
    isBalancesOnlySearch,
    input,
  )

  const isSearchingByAddress = useMemo(() => {
    return Boolean(debouncedSearchFilter && isAddress(debouncedSearchFilter))
  }, [debouncedSearchFilter])

  const isImportedToken = useCallback((currencyInfo: CurrencyInfo): boolean => {
    // Consider a token as "imported" if:
    // 1. We're searching by address AND
    // 2. The token has MediumWarning safety level (which we set for blockchain-fetched tokens)
    return isSearchingByAddress && currencyInfo.safetyLevel === SafetyLevel.MediumWarning
  }, [isSearchingByAddress])

  const onSelectCurrency: OnSelectCurrency = (currencyInfo, section, index) => {
    if (isImportedToken(currencyInfo)) {
      // Show import warning for blockchain-fetched tokens
      setPendingImportToken({ currencyInfo, section, index })
    } else {
      // Proceed normally for known tokens
      parentOnSelectCurrency(currencyInfo, section, index)
      registerSearchTokenCurrencyInfo(currencyInfo)
    }
  }

  const handleImportConfirm = useCallback(() => {
    if (pendingImportToken) {
      // Save the token to user's saved tokens
      addUserToken(pendingImportToken.currencyInfo.currency)
      
      // Call the parent callback with the same signature as normal token selection
      parentOnSelectCurrency(
        pendingImportToken.currencyInfo,
        pendingImportToken.section,
        pendingImportToken.index
      )
      registerSearchTokenCurrencyInfo(pendingImportToken.currencyInfo)
      setPendingImportToken(null)
    }
  }, [pendingImportToken, parentOnSelectCurrency, registerSearchTokenCurrencyInfo, addUserToken])

  const handleImportCancel = useCallback(() => {
    setPendingImportToken(null)
  }, [])

  const userIsTyping = Boolean(searchFilter && debouncedSearchFilter !== searchFilter)

  const emptyElement = useMemo(
    () => (debouncedSearchFilter ? <NoResultsFound searchFilter={debouncedSearchFilter} /> : undefined),
    [debouncedSearchFilter],
  )

  // Show import warning if there's a pending import token
  if (pendingImportToken) {
    return (
      <ImportTokenWarning
        currencyInfo={pendingImportToken.currencyInfo}
        onCancel={handleImportCancel}
        onImport={handleImportConfirm}
      />
    )
  }

  return (
    <TokenSelectorList
      showTokenAddress
      chainFilter={chainFilter}
      emptyElement={emptyElement}
      errorText={t('token.selector.search.error')}
      hasError={Boolean(error)}
      isKeyboardOpen={isKeyboardOpen}
      loading={userIsTyping || loading}
      refetch={refetch}
      sections={sections}
      showTokenWarnings={true}
      onSelectCurrency={onSelectCurrency}
    />
  )
}

export const TokenSelectorSearchResultsList = memo(_TokenSelectorSearchResultsList)
