import { useMemo } from 'react'
import { getAbstractTokenList, nativeOnChain } from 'uniswap/src/constants/tokens'
import { GqlResult } from 'uniswap/src/data/types'
import { ProtectionResult } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { useEnabledChains } from 'uniswap/src/features/chains/hooks/useEnabledChains'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo, TokenList } from 'uniswap/src/features/dataApi/types'
import { buildCurrencyInfo } from 'uniswap/src/features/dataApi/utils'
import { currencyId } from 'uniswap/src/utils/currencyId'

export function useAllCommonBaseCurrencies(): GqlResult<CurrencyInfo[]> {
  const { isTestnetModeEnabled } = useEnabledChains()
  
  const baseCurrencies = useMemo(() => {
    // Use Abstract testnet tokens in testnet mode, mainnet tokens otherwise
    const chainId = isTestnetModeEnabled ? UniverseChainId.Sepolia : UniverseChainId.Mainnet
    
    try {
      const tokens = getAbstractTokenList(chainId)
      const nativeEth = nativeOnChain(chainId)
      
      // Include all tokens including WETH for direct wrapping/unwrapping operations
      const filteredTokens = tokens
      
      const tokenCurrencies = filteredTokens.map(token => 
        buildCurrencyInfo({
          currency: token,
          currencyId: currencyId(token),
          logoUrl: undefined,
          safetyInfo: {
            tokenList: TokenList.Default,
            protectionResult: ProtectionResult.Benign,
          },
        })
      ).filter((c): c is CurrencyInfo => Boolean(c))
      
      // Add native ETH at the beginning with proper safety info
      const nativeCurrency = buildCurrencyInfo({
        currency: nativeEth,
        currencyId: currencyId(nativeEth),
        logoUrl: undefined,
        safetyInfo: {
          tokenList: TokenList.Default,
          protectionResult: ProtectionResult.Benign,
        },
      })

      return nativeCurrency ? [nativeCurrency, ...tokenCurrencies] : tokenCurrencies
    } catch {
      return []
    }
  }, [isTestnetModeEnabled])

  return {
    data: baseCurrencies,
    loading: false,
    error: undefined,
    refetch: () => {},
  }
}
